var hasRecentUpdate = gps_time_last_update.value !== -1 && gps_time_last_update.value <= 30;
var validLatitude = gps_latitude.value >= -90 && gps_latitude.value <= 90;
var validLongitude = gps_longitude.value >= -180 && gps_longitude.value <= 180;
gps_locked.value = hasRecentUpdate && validLatitude && validLongitude;
gps_locked.updated = true;
